def check_constraint(m):
    """Checks if m(m+1) is divisible by 6."""
    if m <= 0:
        return False
    return (m * (m + 1)) % 6 == 0

print("Testing small values of m:")
for m in range(1, 15):
    result = "PASS" if check_constraint(m) else "FAIL"
    print(f"m={m}: {result} (K={m*(m+1)//6 if check_constraint(m) else 'Not Int'})")
